let data=null,session=null,state={page:'overview',scope:'all',month:today().slice(0,7),query:'',business:null,contentEdit:null,taskEdit:null,partnerEdit:null,channelEdit:null,planEdit:null,contentStatus:'all',siteId:null,siteTab:'overview',channel:'all',postStatus:'all',draftSeed:null,promptService:null,promptChannel:'all'},toastTimer,operations=null,accessRequests=[],setupLoading=false,setupError='';
function toast(msg){clearTimeout(toastTimer);$('toast').textContent=msg;$('toast').classList.remove('hidden');toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),6500);}
async function api(route,body){const r=await fetch('/api/dashboard/'+(new URLSearchParams(location.search).has('sample')?'sample/':'')+route,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)}),v=await r.json();if(!r.ok){if((r.status===401||r.status===403)&&session?.authenticated){session.authenticated=false;location.assign(r.status===403?'/access-pending':'/login');}throw new Error(v.error||'작업을 완료하지 못했습니다.');}return v;}
const selected=()=>data.services.filter(s=>state.scope==='all'||s.id===state.scope);
const inScope=s=>state.scope==='all'||s===state.scope;
const service=id=>data.services.find(s=>s.id===id),serviceName=id=>service(id)?.name||id;
const manualBlog=p=>p.channel==='blog'&&(p.blogTarget==='tistory'||!p.blogTarget&&p.service==='tistory');
const manualLabel=p=>manualBlog(p)?'티스토리 직접 발행':`${labels[p.channel]||'채널'} 직접 게시`;
const snsRecord=p=>p?.service==='tistory'&&(!p.business||p.business==='platform');
const supportedChannel=channel=>Object.hasOwn(labels,channel);
const snsPost=p=>snsRecord(p)&&supportedChannel(p.channel);
const platformExcluded=p=>p?.platformExclusion?.status==='excluded';
const visibleRecord=p=>snsRecord(p)&&(!p.channel||p.channel==='all'||supportedChannel(p.channel))&&(!p.channels||p.channels.some(supportedChannel));
const automationPage=()=>['studio','calendar','growth','content','prompts','history','publish','publishing-settings'].includes(state.page);
const snsFields='<input type="hidden" name="service" value="tistory"><input type="hidden" name="business" value="platform"><p class="caption full">SNS 독립 운영 · 다른 서비스의 사업장과 연동하지 않습니다.</p>';
const accountFits=(a,p)=>snsRecord(a)&&snsRecord(p)&&a.channel===p.channel;
const postAccount=p=>data.accounts.find(a=>a.id===p.account)?.label||(p.manual?manualLabel(p):manualBlog(p)?'doto1 · 티스토리':'계정 미지정');
const businessName=(s,id)=>id==='platform'?'서비스 자체':data.businesses.find(b=>b.service===s&&b.id===id)?.name||'사업장';
const amountSum=rows=>rows.reduce((n,r)=>n+Number(r.amount||0),0);
function mark(s){const c=styles[s.id]||['#9eb8c6','#243039',s.name.slice(0,1)];return `<div class="service-logo" style="--c:${c[0]};--t:${c[1]}">${esc(c[2])}</div>`;}
const empty=(message,action='')=>`<div class="empty">${message}${action}</div>`;
const readActions=new Set(['inspect-content','close-inspector','business','go','html','copy','print','csv','export']);
const button=(label,action,id='',kind='')=>session?.readOnly&&!readActions.has(action)||id&&(['content-edit','inspect-edit','create-channel','manual-link','manual-social-link','cancel','studio-open','check-post'].includes(action)&&!snsPost(data.contents.find(p=>p.id===id))||action==='plan-edit'&&!snsRecord(data.plans.find(p=>p.id===id))||action==='prompt-edit'&&!snsRecord(data.prompts.find(p=>p.id===id))||['channel-edit','verify','social-reconnect'].includes(action)&&!snsRecord(data.accounts.find(a=>a.id===id)))?'':`<button class="btn ${kind}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const notice=text=>`<div class="notice">${text}</div>`;
const table=(headers,rows)=>`<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const row=cells=>'<tr>'+cells.map(c=>'<td>'+c+'</td>').join('')+'</tr>';
function formField(label,name,value='',type='text',extra=''){return `<label class="field ${type==='textarea'?'full':''}">${label}${type==='textarea'?`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`;}
function selectField(label,name,items,value=''){return `<label class="field">${label}<select name="${name}">${items.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;}
function serviceFields(s=state.scope==='all'?'mind':state.scope,b='platform',ownedOnly=false){return selectField('서비스','service',data.services.map(x=>[x.id,x.name]),s)+selectField('사업장','business',[['platform','서비스 자체'],...data.businesses.filter(x=>x.service===s&&!x.excluded&&(!ownedOnly||x.owned)).map(x=>[x.id,x.name])],b);}
const checkbox=(label,name,checked=false)=>`<label class="check-label"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;
function disclosure(title,body,open=false){return `<details class="panel disclosure" ${open?'open':''}><summary>${title}</summary><div class="panel-inner">${body}</div></details>`;}
function filteredMoney(allMonths=false){return data.money.filter(r=>!r.voided&&inScope(r.service)&&(allMonths||r.day.startsWith(state.month))&&(r.business==='platform'||data.businesses.some(b=>b.service===r.service&&b.id===r.business&&b.owned&&!b.excluded)));}
function financeTotals(){const records=filteredMoney(),revenue=amountSum(records.filter(r=>r.kind==='income'))-amountSum(records.filter(r=>r.kind==='refund')),cost=amountSum(records.filter(r=>r.kind==='expense'))-amountSum(records.filter(r=>r.kind==='expense_refund'));
 const scopes=selected().flatMap(s=>[{service:s.id,business:'platform'},...data.businesses.filter(b=>b.service===s.id&&b.owned&&!b.excluded).map(b=>({service:s.id,business:b.id}))]);
 const complete=scopes.length>0&&scopes.every(s=>data.coverage.some(c=>c.service===s.service&&c.business===s.business&&c.month===state.month&&c.complete));return {records,revenue:records.some(r=>['income','refund'].includes(r.kind))||complete?revenue:null,cost:records.some(r=>['expense','expense_refund'].includes(r.kind))||complete?cost:null,profit:complete?revenue-cost:null,margin:complete&&revenue>0?(revenue-cost)/revenue*100:null,complete};}
function kpis(){const t=financeTotals();return '<div class="kpis">'+[['기록 매출',t.revenue,t.complete?'월별 입력 확인 완료':'확인한 거래 · 부분 집계','chart'],['기록 비용',t.cost,t.complete?'월별 입력 확인 완료':'원가 · 인건비 · 서버 등','file'],['영업 손익',t.profit,t.complete?'기록 매출 − 기록 비용':'월별 입력 확인 후 계산','grid'],['이익률',t.margin==null?null:t.margin.toFixed(1)+'%',t.complete?'영업 손익 / 기록 매출':'비용 확인 필요','chart']].map(([l,v,n,i])=>'<div class="kpi"><div class="kpi-label">'+l+icon(i)+'</div><div class="kpi-number '+(v==null?'unset':'')+'">'+(v==null?'미확인':typeof v==='number'?money(v)+'<small>원</small>':v)+'</div><div class="kpi-change">'+(t.complete?'<span class="positive">'+icon('check')+'</span>':'')+n+'</div></div>').join('')+'</div>';}
function observations(){return selected().flatMap(s=>(s.snapshot?.data?.monthly||[]).filter(r=>r.month===state.month).map(r=>({...r,service:s.id,owned:data.businesses.some(b=>b.service===s.id&&b.id===r.businessId&&b.owned&&!b.excluded)})));}
function sourceTable(){const rows=observations().filter(r=>r.businessId).map(r=>row([esc(serviceName(r.service)),esc(businessName(r.service,r.businessId)),r.owned?'<span class="pill">직영</span>':'<span class="pill gray">일반 사업장</span>',esc(metricsLabels[r.metric]||'매장 수납 스냅샷'),won(r.service==='holdem'?Number(r.storedReceipts)+Number(r.storedAddonReceipts):r.amount),money(r.records)+'건']));return `<section class="panel section-gap"><div class="table-head"><h2>원천 실적 대조</h2><p class="panel-desc">서비스 내 거래와 누리 매출 기록을 구분합니다.</p></div>${rows.length?table(['서비스','사업장','누리 귀속','집계 기준','금액','기록'],rows):empty('이 달의 원천 거래가 없습니다. 월 선택에서 다른 기간을 확인하세요.')}<div class="panel-foot">수납·청구·비용은 서로 합산하지 않습니다. 직영 선택만으로 매출이 확정되지는 않습니다.</div></section>`;}
function serviceSummary(){return `<section class="panel section-gap"><div class="table-head"><h2>웹사이트별 현황</h2><p class="panel-desc">실제 조회 결과 · 회원과 고객 수는 테스트를 포함한 원천 전체 건수입니다.</p></div>${table(['웹사이트','회원 / 고객','사업장','운영 정보','데이터 상태'],selected().map(s=>{const d=s.snapshot?.data||{};return row([`<div class="service-name">${mark(s)}<div class="service-info"><b>${esc(s.name)}</b><small>${esc(s.note)}</small></div></div>`,d.users!=null?money(d.users)+'명':d.customers!=null?money(d.customers)+'개':'미연결',d.sourceBusinesses!=null?money(d.sourceBusinesses)+'개':'—',s.id==='mind'?`게시물 ${money(d.posts)}개`:s.id==='holdem'?`참가 기록 ${money(d.buyins)}건 · 세션 ${money(d.sessions)}개`:s.id==='crm'?`장부 ${money(d.ledgerRecords)}건`:s.id==='market'&&d.orders!=null?`주문 ${money(d.orders)}건 · 상품 ${money(d.products)}개`:s.id==='tistory'&&d.posts!=null?`공개 글 ${money(d.posts)}개`:'수집 연결 필요',`<span class="pill ${s.stale?'amber':''}">${s.snapshot?.data?(s.stale?'이전 조회':'조회 성공'):'연결 필요'}</span><small class="row-note">${dt(d.observedAt)}</small>`]);}))}</section>`;}
function monthlyChart(){const months=[...new Set(data.services.flatMap(s=>(s.snapshot?.data?.monthly||[]).map(r=>r.month)).concat(data.money.map(r=>r.day.slice(0,7)),state.month))].sort().slice(-6);const records=filteredMoney(true);const values=months.map(m=>({rev:amountSum(records.filter(r=>r.day.startsWith(m)&&r.kind==='income'))-amountSum(records.filter(r=>r.day.startsWith(m)&&r.kind==='refund')),cost:amountSum(records.filter(r=>r.day.startsWith(m)&&r.kind==='expense'))-amountSum(records.filter(r=>r.day.startsWith(m)&&r.kind==='expense_refund'))}));const max=Math.max(1,...values.flatMap(v=>[Math.abs(v.rev),Math.abs(v.cost)])),negative=values.some(v=>v.rev<0||v.cost<0),baseline=negative?100:180,scale=negative?70:140;return `<section class="panel"><div class="panel-inner"><div class="panel-head"><div><h2>월별 기록 매출 · 비용</h2><p class="panel-desc">직영으로 지정한 사업장과 서비스 자체 기록</p></div><div class="legend"><span><i style="background:#65d6a5"></i>매출</span><span><i style="background:#779baa"></i>비용</span></div></div>${records.length?`<svg class="chart" viewBox="0 0 620 220" role="img" aria-label="월별 매출 비용 막대그래프"><path d="M45 20v${baseline-20}h550" fill="none" stroke="#343f47"/>${months.map((m,i)=>{const x=65+i*(510/Math.max(1,months.length));return `<rect x="${x}" y="${baseline-Math.max(0,values[i].rev)/max*scale}" width="22" height="${Math.abs(values[i].rev)/max*scale}" fill="#65d6a5"/><rect x="${x+25}" y="${baseline-Math.max(0,values[i].cost)/max*scale}" width="22" height="${Math.abs(values[i].cost)/max*scale}" fill="#779baa"/><text x="${x+23}" y="205" text-anchor="middle">${m.slice(5)}월</text>`;}).join('')}</svg>`:empty('아직 확인된 매출·비용 기록이 없습니다.<br>거래를 입력하면 월별 그래프가 표시됩니다.',button('거래 입력','go','finance','empty-action'))}</div></section>`;}
function workSummary(){const tasks=data.tasks.filter(t=>inScope(t.service)&&t.status!=='done'),posts=data.contents.filter(p=>snsPost(p)&&inScope(p.service));return `<section class="panel panel-inner"><div class="panel-head"><div><h2>오늘의 운영</h2><p class="panel-desc">업무와 콘텐츠 상태를 함께 확인합니다.</p></div>${icon('task')}</div><div class="metric-grid" style="margin-top:19px">${[['진행할 업무',tasks.length],['기한 지난 업무',tasks.filter(t=>t.due&&t.due<today()).length],['예약 콘텐츠',posts.filter(p=>p.status==='scheduled').length],['게시 완료',posts.filter(p=>p.status==='published'&&!platformExcluded(p)).length],['플랫폼 삭제 제외',posts.filter(platformExcluded).length],['확인할 게시',posts.filter(p=>p.status==='review').length],['연결한 채널',data.accounts.filter(a=>snsRecord(a)&&supportedChannel(a.channel)&&inScope(a.service)&&a.verifiedAt).length]].map(([l,v])=>`<div class="metric-tile"><strong>${v}</strong><span class="caption">${l}</span></div>`).join('')}</div><div class="toolbar">${button('업무 관리','go','tasks')}${button('콘텐츠 운영','go','content')}</div></section>`;}
function overview(){return kpis()+sectionHeading('매출과 비용의 흐름','선택한 월과 최근 6개월의 기록을 비교합니다.','')+'<div class="two-col">'+monthlyChart()+costBreakdown()+'</div>'+sectionHeading('웹사이트별 현황','각 사이트의 실적과 운영을 따로 확인할 수 있습니다.',button('웹사이트 추가','go','connections','text'))+siteCards()+sectionHeading('SNS 업로드 현황','실제 게시 시각 확인분과 예약·확인 필요 항목을 모았습니다.',button('전체 업로드 보기 ↗','go','publish','text'))+publicationPulse()+publishingBoard(4)+sectionHeading('지금 처리할 업무','진행 중인 업무와 가까운 마감 일정입니다.',button('업무 전체 보기 ↗','go','tasks','text'))+taskBrief();}
function businessPage(){const bs=data.businesses.filter(b=>inScope(b.service));return `<section class="panel section-gap"><div class="table-head"><h2>사업장 목록 <span class="pill gray">${bs.length}개</span></h2><p class="panel-desc">테스트·체험 사업장은 집계에서 제외합니다. 같은 이름의 사업장도 원천 ID로 구분합니다.</p></div>${bs.length?table(['사업장','서비스 / 업종','활동 상태','실적 포함','관리'],bs.map(b=>row([`<b>${esc(b.name)}</b><small class="row-note">${esc(b.id.slice(0,8))}</small>`,`${esc(serviceName(b.service))}<small class="row-note">${esc(({building:'건물관리',factory:'맞춤제작',rental:'렌탈',salon:'미용',academy:'학원',unmanned:'무인매장'})[b.industry]||'홀덤 매장')}</small>`,b.excluded?'<span class="pill gray">테스트 / 체험</span>':`<span class="pill ${b.active?'':'gray'}">${b.active?'활동 중':'비활성'}</span>`,`<label class="check-label"><input type="checkbox" data-own="${esc(b.key)}" ${b.owned?'checked':''} ${b.excluded?'disabled':''}>직영 포함</label>`,button('상세 보기','business',b.key)]))):empty('이 서비스에는 연결된 사업장이 없습니다.')}</section>`+businessDetail();}
function businessDetail(){const b=data.businesses.find(b=>b.key===state.business);if(!b)return `<p class="caption">상세 보기에서 원천 실적, 비용 항목, 연결 업무를 확인할 수 있습니다.</p>`;const d=service(b.service).snapshot?.data,op=d?.operations?.find(x=>x.businessId===b.id),monthly=(d?.monthly||[]).filter(r=>r.businessId===b.id&&r.month===state.month);const expenses=(d?.expenseDetails||[]).filter(r=>r.businessId===b.id&&r.month===state.month);return `<section class="panel panel-inner section-gap"><div class="panel-head"><div><h2>${esc(b.name)}</h2><p class="panel-desc">${esc(serviceName(b.service))} · ${b.owned?'직영 사업장':'직영 미지정'} · ${state.month}</p></div>${service(b.service).url?`<a class="btn" href="${esc(service(b.service).url)}" target="_blank" rel="noopener noreferrer">원본 서비스 열기 ↗</a>`:''}</div>${op?`<div class="metric-grid" style="margin-top:20px">${[['고객',op.customers],['건물',op.buildings],['활성 호실',op.units],['현재 계약',op.activeContracts],['미완료 작업',op.openWorkOrders],['미완료 제작 주문',op.pendingFactoryOrders]].map(([l,v])=>`<div class="metric-tile"><strong>${money(v)}</strong><span class="caption">${l}</span></div>`).join('')}</div><div class="pl-row"><span>관리비 미수 원장 잔액 · 현재 상태</span><strong>${won(op.outstanding)}</strong></div>`:''}${monthly.map(r=>`<div class="pl-row"><span>${esc(metricsLabels[r.metric]||'매장 수납 스냅샷')}</span><strong>${won(b.service==='holdem'?r.storedReceipts+r.storedAddonReceipts:r.amount)}</strong></div>`).join('')}${b.service==='holdem'?monthly.map(r=>`<p class="source-note">수납 ${r.records}건 · 저장 미수 ${won(r.storedUnpaid)} · 과거 산식 재확인 ${r.legacyRecords}건 · VAT 구분 미확인</p>`).join(''):''}${!monthly.length?empty('선택 월의 원천 금액이 없습니다.'):''}<p class="source-note">원본의 주문·계약·수납 변경은 해당 서비스에서 처리합니다. NURI ONE의 업무와 비용 기록은 아래 통합 관리에서 저장됩니다.</p></section>${expenses.length?`<section class="panel section-gap"><div class="table-head"><h2>건물 비용 상세 · 발생/입력 기준</h2></div>${table(['분류','거래처','공급가액','VAT','원천 ID'],expenses.map(e=>row([esc(e.category),esc(e.vendor||'미입력'),won(e.supply),won(e.vat),esc(e.id.slice(0,8))])))}</section>`:''}`;}
function moneyForm(){return `<form id="money-form" class="form-grid" data-owned-only="true">${serviceFields(undefined,undefined,true)}${formField('거래일','day',today(),'date','required')}${selectField('거래 유형','kind',[['income','매출'],['expense','비용'],['refund','매출 환불'],['expense_refund','비용 환급']])}${formField('금액 · 원','amount','','number','min="1" step="1" required')}${formField('분류','category','','text','placeholder="예: 구독료, 서버, 인건비" required')}${formField('거래처','partner','','text','maxlength="120"')}${formField('거래 고유번호 / 증빙번호','reference','','text','placeholder="중복 입력을 막는 고유번호" maxlength="160" required')}${formField('매출 인식 / 비용 근거 · VAT 제외 여부','note','','textarea','placeholder="원천 수납과 같은 거래라면 중복 입력하지 마세요."')}<div class="full"><button class="btn primary" type="submit">거래 저장</button><p class="source-note">확인한 누리 매출과 비용을 입력합니다. 원천 수납·부과를 자동으로 더하지 않습니다.</p></div></form>`;}
function coverageForm(){return `<form id="coverage-form" class="form-grid" data-owned-only="true">${serviceFields(undefined,undefined,true)}${formField('확인 월','month',state.month,'month','required')}<div>${checkbox('이 사업장/서비스의 월 매출·원가·운영비 입력을 모두 확인했습니다.','complete')}</div><div class="full"><button type="submit" class="btn">입력 확인 저장</button><p class="source-note">선택 범위의 모든 서비스 자체와 직영 사업장이 확인되어야 영업 손익을 계산합니다.</p></div></form>`;}
function finance(){const t=financeTotals();return kpis()+disclosure('매출 · 비용 입력',moneyForm())+disclosure('월별 입력 완전성 확인',coverageForm())+`<section class="panel section-gap"><div class="table-head"><div class="panel-head"><h2>통합 거래 기록 <span class="pill gray">${t.records.length}건</span>${button('CSV 다운로드','csv')}</div></div>${t.records.length?table(['거래일','서비스 / 사업장','유형 / 분류','거래처','금액','증빙번호','관리'],t.records.map(r=>row([r.day,`${esc(serviceName(r.service))}<small class="row-note">${esc(businessName(r.service,r.business))}</small>`,esc(({income:'매출',expense:'비용',refund:'매출 환불',expense_refund:'비용 환급'})[r.kind])+' / '+esc(r.category),esc(r.partner),won(r.amount),esc(r.reference),button('취소 기록','void',r.id,'danger-btn')]))):empty('이 월에 기록한 누리 매출·비용이 없습니다. 위의 입력 양식에서 거래를 저장하세요.')}<div class="panel-foot">거래 고유번호로 중복을 차단합니다. 취소는 기록을 남기며, 직영 해제된 사업장 거래는 누리 합계에서 제외됩니다.</div></section>`+sourceTable()+`<section class="panel panel-inner"><h2>집계 기준</h2><p class="pl-note">금액은 원 단위입니다. 수납과 매출을 별도로 대조하며, 보증금·포인트·미수금은 자동 매출에 포함하지 않습니다. 원천 비용과 통합 입력 비용도 중복 합산하지 않습니다. 부가세, 원가, 공통비 배부는 입력 근거를 확인하세요. 법인세·이자까지 포함한 당기순이익은 현재 집계하지 않습니다.</p></section>`;}
function partnerRows(){return [...(data.partners||[]).filter(p=>inScope(p.service)).map(p=>({...p,key:'manual:'+p.id})),...selected().flatMap(s=>[...(s.snapshot?.data?.corporatePartners||[]).map(p=>({...p,service:s.id,type:'법인 거래처',key:s.id+':party:'+p.id})),...(s.snapshot?.data?.partners||[]).filter(p=>!p.excluded).map(p=>({...p,service:s.id,type:s.id==='holdem'?'연결 매장':'CRM 사업장',key:s.id+':business:'+p.id}))])];}
function partnerTable(q=''){const ps=partnerRows().filter(p=>p.name.toLocaleLowerCase().includes(q.trim().toLocaleLowerCase()));return ps.length?table(['거래처 이름','서비스','관계','상태','원천 구분'],ps.map(p=>row([esc(p.name),esc(serviceName(p.service)),esc(p.type),p.active?'활동 중':'비활성',p.key.startsWith('manual:')?button('수정','partner-edit',p.id):esc(p.key.split(':').slice(1).join(':').slice(0,16))]))):empty('검색 결과가 없습니다.');}
function partners(){const ps=partnerRows(),p=(data.partners||[]).find(x=>x.id===state.partnerEdit);return disclosure(p?'거래처 수정':'통합 거래처 등록',`<form id="partner-form" class="form-grid"><input type="hidden" name="id" value="${esc(p?.id||'')}">${selectField('서비스','service',data.services.map(s=>[s.id,s.name]),p?.service)}${formField('거래처 이름','name',p?.name||'','text','required maxlength="120"')}${selectField('관계 유형','type',[['고객사','고객사'],['공급사','공급사'],['운영 파트너','운영 파트너'],['콘텐츠 파트너','콘텐츠 파트너']],p?.type)}${formField('담당자','owner',p?.owner||'')}${formField('관리 메모','note',p?.note||'','textarea')}<div class="full">${checkbox('활동 중','active',p?.active!==false)}<button class="btn primary" type="submit">거래처 저장</button><p class="source-note">통합 거래처는 이 대시보드에 저장합니다. 원본 서비스 거래처를 같은 이름으로 다시 등록하면 별도 항목으로 표시됩니다.</p></div></form>`,!!p)+`<section class="panel"><div class="table-head panel-head"><div><h2>연결된 거래처 · ${ps.length}개</h2><p class="panel-desc">원천 ID와 통합 등록 ID 기준 · 이름만으로 합치지 않습니다.</p></div><label class="compact-search">${icon('search')}<input id="partner-search" type="search" value="${esc(state.query)}" placeholder="거래처 이름 검색" aria-label="거래처 이름 검색"></label></div><div id="partner-results">${partnerTable(state.query)}</div><div class="panel-foot">연락처·계좌·고객 개인 정보는 수집하지 않습니다. 거래 금액은 연결된 증빙이 있을 때만 확인합니다.</div></section>`;}
function traffic(){const s=service('tistory'),d=s?.snapshot?.data,r=data.google?.reports?.find(r=>r.month===state.month),unknown=data.google?.configured||data.demo?'미확인':'미연결';return adsensePanel()+`<section class="panel panel-inner section-gap"><div class="panel-head"><div><h2>티스토리 · doto1</h2><p class="panel-desc">https://doto1.tistory.com · GA4 G-174JZ8W7VK</p></div><a class="btn" href="https://doto1.tistory.com" target="_blank" rel="noopener noreferrer">블로그 열기 ↗</a></div><div class="toolbar"><span class="pill">서치콘솔 등록 완료 · 사용자 확인</span><span class="pill ${data.google?.configured||data.demo?'':'gray'}">통계 조회 ${data.google?.configured||data.demo?'연결됨':'권한 연결 필요'}</span><span class="pill gray">사이트맵 글 ${d?.posts==null?'미조회':money(d.posts)+'개'}</span></div><p class="caption">등록 상태와 API 조회 권한은 별도입니다. 블로그에는 측정 태그를 다시 삽입하지 않습니다.</p></section><div class="metric-grid section-gap">${[['GA4 활성 사용자',r?.ga?.users],['세션',r?.ga?.sessions],['페이지 조회',r?.ga?.views],['검색 클릭',r?.search?.clicks],['검색 노출',r?.search?.impressions],['평균 검색 순위',r?.search?.position?.toFixed(1)]].map(([l,v])=>`<div class="metric-tile"><strong>${v==null?unknown:money(v)}</strong><span class="caption">${l}</span></div>`).join('')}</div><section class="panel panel-inner section-gap"><div class="panel-head"><h2>${state.month} 유입 통계</h2>${button('통계 조회','google-report')}</div><p class="source-note">최근 통계 조회 ${dt(r?.observedAt)} KST · CTR ${r?.search?.ctr!=null?(r.search.ctr*100).toFixed(2)+'%':unknown} · GA4 기록 수익 ${won(r?.ga?.revenue)}</p>${r?.gaError?notice(esc(r.gaError)):''}${r?.searchError?notice(esc(r.searchError)):''}<p class="caption">GA4는 doto1.tistory.com만 조회하며 범위를 확인하지 못한 과거 집계는 숨깁니다. GA4 수익은 이벤트 연동 결과이며 정산 매출과 자동 합산하지 않습니다. 검색어 표는 상위 100개이며 익명화된 검색어는 포함되지 않을 수 있습니다.</p></section>${r?.queries?.length?`<section class="panel section-gap"><div class="table-head"><h2>검색 유입 키워드</h2></div>${table(['검색어','클릭','노출','CTR','평균 순위'],r.queries.map(q=>row([esc(q.keys?.[0]),money(q.clicks),money(q.impressions),Number.isFinite(q.ctr)?(q.ctr*100).toFixed(2)+'%':unknown,Number.isFinite(q.position)?q.position.toFixed(1):unknown])))}</section>`:''}`+disclosure('GA4 · 서치콘솔 조회 권한 연결',`<form id="google-form" class="form-grid">${formField('GA4 숫자 속성 ID','propertyId',data.google?.propertyId||'','text','placeholder="예: 123456789 · G- 측정 ID와 다름" pattern="[0-9]*"')}${selectField('서치콘솔 속성','siteUrl',[['https://doto1.tistory.com/','URL 접두어: https://doto1.tistory.com/'],['sc-domain:doto1.tistory.com','도메인: doto1.tistory.com']],data.google?.siteUrl)}${formField('Google 서비스 계정 JSON','credentials','','textarea','required autocomplete="off" spellcheck="false" placeholder="서비스 계정 이메일에 GA4 읽기 및 서치콘솔 접근 권한을 부여한 뒤 JSON을 입력하세요."')}<div class="full"><button class="btn primary" type="submit">조회 계정 저장</button><p class="source-note">읽기 전용 범위로 요청합니다. 키는 암호화해 저장하고 화면에는 다시 표시하지 않습니다. Google Analytics Data API 활성화와 속성 접근 권한이 필요합니다.</p></div></form>`)+`<section class="panel"><div class="table-head"><h2>${data.demo?'샘플 글 목록 · 일부 예시':'공개 글 목록 · 사이트맵 기준'}</h2><p class="panel-desc">카테고리·모바일·공지 주소를 제외하고 글 URL을 수집합니다. 제목은 URL의 글 식별자입니다.</p></div>${d?.publishedPosts?.length?table(['글 식별자','최근 수정','바로가기'],d.publishedPosts.map(p=>row([`<span class="overflow-text">${esc(p.title)}</span>`,dt(p.modifiedAt),`<a class="link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">글 열기 ↗</a>`]))):empty('아직 사이트맵 글 목록이 없습니다. 전체 새로고침을 실행하세요.')}<div class="panel-foot">사이트맵은 공개 목록입니다. 비공개 글이나 티스토리 관리자 통계는 포함하지 않습니다.</div></section>`;}
function tasks(){const editing=data.tasks.find(t=>t.id===state.taskEdit);return disclosure(editing?'업무 수정':'새 업무 등록',`<form id="task-form" class="form-grid"><input type="hidden" name="id" value="${esc(editing?.id||'')}">${serviceFields(editing?.service,editing?.business)}${formField('업무 제목','title',editing?.title||'','text','required maxlength="200"')}${formField('담당자','assignee',editing?.assignee||'')}${formField('기한','due',editing?.due||'','date')}${selectField('상태','status',[['todo','할 일'],['doing','진행 중'],['done','완료'],['hold','보류']],editing?.status)}${selectField('우선순위','priority',[['normal','보통'],['high','높음']],editing?.priority)}${formField('업무 내용','note',editing?.note||'','textarea')}<div class="full"><button class="btn primary" type="submit">업무 저장</button></div></form>`,!!editing)+`<div class="task-columns">${[['todo','할 일'],['doing','진행 중'],['done','완료'],['hold','보류']].map(([status,title])=>{const ts=data.tasks.filter(t=>inScope(t.service)&&t.status===status);return `<section class="task-col"><h2>${title} · ${ts.length}</h2>${ts.map(t=>`<article class="task-card"><div class="status-row"><strong>${esc(t.title)}</strong>${t.priority==='high'?'<span class="pill amber">높음</span>':''}</div><p>${esc(t.note)}</p><div class="caption">${esc(serviceName(t.service))} · ${esc(businessName(t.service,t.business))}<br>${esc(t.assignee||'담당 미지정')} · ${t.due||'기한 없음'}${t.due&&t.due<today()&&status!=='done'?' · 기한 지남':''}</div><select class="select" data-task-status="${esc(t.id)}" aria-label="${esc(t.title)} 상태">${[['todo','할 일'],['doing','진행 중'],['done','완료'],['hold','보류']].map(([v,l])=>`<option value="${v}" ${v===status?'selected':''}>${l}</option>`).join('')}</select><div class="toolbar">${button('수정','task-edit',t.id)}</div></article>`).join('')||'<p class="caption">등록된 업무가 없습니다.</p>'}</section>`;}).join('')}</div>`;}
function channelCheckboxes(selected=['blog','instagram','threads','x']){return `<div class="full"><span class="caption">사용할 채널</span><div class="toolbar">${Object.entries(labels).map(([id,label])=>checkbox(label,'channel_'+id,selected.includes(id))).join('')}</div></div>`;}
function content(){const editing=data.contents.find(p=>p.id===state.contentEdit&&snsPost(p))||(snsPost(state.draftSeed)?state.draftSeed:null);const posts=data.contents.filter(p=>snsPost(p)&&inScope(p.service)&&(state.channel==='all'||p.channel===state.channel)&&(state.contentStatus==='all'||p.status===state.contentStatus));return automationTabs()+channelTabs()+`<div id="channel-panel" role="tabpanel" aria-labelledby="channel-tab-${state.channel}"><div class="metric-grid section-gap">${[['초안',posts.filter(p=>p.status==='draft').length],['예약 / 게시 중',posts.filter(p=>['scheduled','publishing'].includes(p.status)).length],['게시 완료',posts.filter(p=>p.status==='published').length]].map(([l,v])=>`<div class="metric-tile"><strong>${v}</strong><span class="caption">${l}</span></div>`).join('')}</div>`+disclosure('AI로 채널별 초안 만들기',`<form id="generate-form" class="form-grid">${snsFields}${formField('콘텐츠 주제','topic','','text','required placeholder="예: 신규 서비스 소개, 이용 방법 안내" maxlength="1200"')}${formField('대상 독자 · 선택','audience','','text','maxlength="500" placeholder="어떤 상황의 독자에게 도움이 되나요?"')}${formField('핵심 키워드 · 선택','keyword','','text','maxlength="200"')}${formField('콘텐츠의 목표 · 선택','objective','','text','maxlength="500" placeholder="예: 제휴 상품 비교, 자료집 판매, 상담 유입"')}${formField('다음 행동 · 선택','cta','','text','maxlength="500" placeholder="확인된 링크와 독자가 할 행동"')}${formField('이번 콘텐츠 어조 · 선택','tone','','text','maxlength="200" placeholder="비우면 저장된 채널별 어조를 사용합니다."')}${formField('이번 콘텐츠 추가 지시 · 선택','instructions','','textarea','maxlength="5000" placeholder="저장된 프롬프트에 이번 생성에만 적용할 지시를 추가합니다."')}${formField('공개해도 되는 참고자료','context','','textarea','placeholder="상품 설명·공개 URL·제공 내용. 고객 개인정보나 매출 자료는 넣지 마세요." maxlength="5000"')}${channelCheckboxes(state.channel==='all'?Object.keys(labels):[state.channel])}<div class="full"><button class="btn primary" type="submit">${icon('content')} AI 초안 생성</button><p class="source-note">${data.demo?'샘플 생성 예시 · 실제 AI 호출 없음':data.ai.installed?'설정한 AI API로 생성합니다.':'설정에서 AI API를 연결해주세요.'} 생성한 글은 초안으로 저장됩니다.</p><p class="action-error" id="generate-message" role="status"></p></div></form>`)+disclosure(editing?'콘텐츠 수정':'직접 콘텐츠 작성',`<form id="content-form" class="form-grid"><input type="hidden" name="id" value="${esc(editing?.id||'')}"><input type="hidden" name="version" value="${editing?.id?Number(editing.version||1):''}"><input type="hidden" name="campaignId" value="${esc(editing?.campaignId||'')}">${snsFields}${selectField('채널','channel',Object.entries(labels),editing?.channel||(state.channel==='all'?'blog':state.channel))}${selectField('블로그 발행 방식','blogTarget',[['wordpress','WordPress · 자동 발행'],['tistory','티스토리 doto1 · 직접 발행']],editing?.blogTarget||(editing?.service==='tistory'||!editing&&state.scope==='tistory'?'tistory':'wordpress'))}${formField('제목','title',editing?.title||'','text','required maxlength="300"')}${formField('본문','body',editing?.body||'','textarea','required maxlength="20000"')}${formField('인스타그램 공개 이미지 주소','media',editing?.media||'','url','placeholder="https://...jpg"')}<div class="full"><button class="btn primary" type="submit">초안 저장</button>${editing?.status==='scheduled'?'<p class="source-note">저장하면 현재 예약이 해제되고 초안으로 돌아갑니다.</p>':''}</div></form>`,!!editing)+`<div class="panel-head section-gap"><h2>콘텐츠 목록</h2><select class="select" id="content-status" aria-label="콘텐츠 상태"><option value="all">모든 상태</option>${Object.entries(statusLabels).map(([v,l])=>`<option value="${v}" ${v===state.contentStatus?'selected':''}>${l}</option>`).join('')}</select>${button('채널 계정 연결','go','connections')}</div><div class="content-grid">${posts.map(p=>contentCard(p)).join('')||`<div class="panel">${empty('아직 콘텐츠가 없습니다.<br>AI 초안을 만들거나 직접 작성하세요.')}</div>`}</div></div>`;}
function contentCard(p){if(!snsRecord(p))return `<article class="panel content-card"><div class="status-row"><span>${esc(serviceName(p.service))} · ${esc(labels[p.channel])}</span><span class="pill gray">기존 기록 · 조회 전용</span></div><h2>${esc(p.title)}</h2><p>${esc(p.body)}</p><p class="caption">${esc(statusLabels[p.status]||p.status)} · ${dt(p.createdAt)}</p><div class="toolbar">${button('상세','inspect-content',p.id)}${button('본문 복사','copy',p.id)}</div></article>`;if(manualChannels.has(p.channel))return manualChannelCard(p);if(manualBlog(p))return tistoryCard(p);const accounts=data.accounts.filter(a=>accountFits(a,p)&&a.verifiedAt);return `<article class="panel content-card"><div class="status-row"><span class="channel-name">${labels[p.channel]} · ${esc(serviceName(p.service))}</span><span class="pill ${p.status==='review'?'amber':p.status==='draft'?'gray':''}">${statusLabels[p.status]}</span></div><h2 style="margin-top:16px">${esc(p.title)}</h2><p>${esc(p.body)}</p><div class="caption">${esc(businessName(p.service,p.business))} · ${p.ai?(data.demo?'AI 초안 샘플':'AI 초안'):'직접 작성'} · ${dt(p.createdAt)}</div>${p.error?`<p class="warning">${esc(p.error)}</p>`:''}${p.scheduledAt?`<p class="caption">예약 ${dt(p.scheduledAt)} KST</p>`:''}${p.status==='published'?`<div class="toolbar">${p.link?`<a class="btn" href="${esc(webLink(p.link))}" target="_blank" rel="noopener noreferrer">게시물 보기 ↗</a>`:''}<span class="caption">${p.manual?'URL 등록 · API ID 없음':'게시 ID '+esc(p.externalId)}</span></div>`:p.status==='publishing'?'<p class="caption">채널 응답을 기다리고 있습니다.</p>':`<div class="toolbar">${button('본문 수정','content-edit',p.id)}${button('복사','copy',p.id)}${manualUrlChannels.has(p.channel)&&!p.externalId&&['draft','approved','review'].includes(p.status)?button('직접 게시 URL 등록','manual-social-link',p.id):''}${p.status==='scheduled'?button('예약 취소','cancel',p.id):''}</div>${p.status!=='scheduled'?`<form class="schedule-form form-grid" data-id="${esc(p.id)}" style="margin-top:18px">${selectField('게시 계정','account',accounts.length?accounts.map(a=>[a.id,a.label]):[['','연결된 계정 없음']])}${formField('예약 시각 · KST','at','','datetime-local')}${p.status==='review'?`<div class="full">${checkbox('채널에서 기존 게시물이 없음을 직접 확인했습니다.','checked')}</div>`:''}<div class="full"><button class="btn primary" type="submit" ${!accounts.length?'disabled':''}>${icon('arrow')} 예약 / 즉시 게시 승인</button><p class="source-note">시각을 비우면 다음 실행 주기에 즉시 게시합니다.</p></div></form>`:''}`}</article>`;}
function planForm(){const p=data.plans.find(p=>p.id===state.planEdit&&snsRecord(p));return `<form id="plan-form" class="form-grid"><input type="hidden" name="id" value="${esc(p?.id||'')}">${snsFields}${formField('반복 기획 주제','topic',p?.topic||'','text','required placeholder="예: 서비스 활용 팁을 매번 다른 관점으로 작성"')}${formField('생성 주기 · 일','days',p?.days||'7','number','min="1" max="365" step="1" required')}${formField('첫 생성 시각 · KST','at',p?.nextAt?new Date(Date.parse(p.nextAt)+9*3600000).toISOString().slice(0,16):'','datetime-local','required')}${formField('어조 · 선택','tone',p?.tone||'','text','maxlength="200" placeholder="비우면 저장된 채널별 설정을 사용합니다."')}${formField('반복 기획 추가 지시','instructions',p?.instructions||'','textarea','maxlength="5000"')}${formField('공개 참고자료','context',p?.context||'','textarea','maxlength="5000"')}${channelCheckboxes(p?.channels||(state.channel==='all'?['blog','threads','x']:[state.channel]))}<div class="full">${checkbox('기획 활성화','enabled',p?.enabled)}${checkbox('연결된 블로그·Threads·X 계정으로 생성 후 자동 게시','autoPublish',p?.autoPublish)}<p class="source-note">인스타그램은 이미지 주소를 넣은 뒤 게시를 승인합니다. 예약은 게시 서버가 실행 중일 때 동작합니다. 과거 시각의 기획은 다음 실행 주기에 한 번 실행됩니다.</p><button class="btn primary" type="submit">반복 기획 저장</button></div></form>`;}
function planList(){const plans=data.plans.filter(p=>(snsRecord(p)&&inScope(p.service))&&(p.channels?.some(supportedChannel)&&(state.channel==='all'||p.channels.includes(state.channel))));return plans.length?`<section class="panel section-gap">${plans.map(p=>`<div class="plan-row"><div class="status-row"><h2>${esc(p.topic)}</h2><label class="check-label"><input type="checkbox" data-plan="${esc(p.id)}" ${p.enabled?'checked':''} ${snsRecord(p)?'':'disabled'}>${snsRecord(p)?'활성화':'기존 기록 · 조회 전용'}</label></div><p>${esc(serviceName(p.service))} · ${p.days}일 주기 · ${p.channels.filter(supportedChannel).map(c=>labels[c]).join(', ')} · ${snsRecord(p)?(p.autoPublish?'자동 게시':'초안 저장'):'기존 기획 · 조회 전용'}<br>${snsRecord(p)?'다음 생성':'기존 예정 시각'} ${dt(p.nextAt)} KST${p.lastResult?'<br>최근 실행: '+esc(p.lastResult):''}</p><div class="toolbar">${button('수정','plan-edit',p.id)}</div></div>`).join('')}</section>`:'';}
function servers(){return notice('DB 조회 결과는 마지막 조회 시점의 상태입니다. 서버 가동률·CPU·실시간 오류·공급자 비용은 모니터링/청구 API 연결 전입니다.')+`<section class="panel section-gap">${selected().map(s=>`<div class="connection-item"><div class="service-name">${mark(s)}<div><h2>${esc(s.name)}</h2><p>${s.snapshot?.data?'최근 성공 '+dt(s.snapshot.data.observedAt)+' KST':'아직 조회되지 않았습니다.'}</p><p>${esc(s.snapshot?.error||s.note)}</p></div></div><span class="pill ${s.stale?'amber':''}">${s.snapshot?.data?s.stale?'오래된 결과 / 재조회 필요':'조회 성공':'미연결'}</span></div>`).join('')}</section><section class="panel panel-inner"><h2>확인할 운영 항목</h2>${[['데이터베이스','MIND · HOLDEM · CRM / 기존 Supabase CLI 인증'],['MARKET','동일 운영 DB · 상세 주문은 쇼핑몰 관리에서 처리'],['호스팅 상태','실제 배포 SHA·헬스체크·오류 수집 연결 필요'],['서버 · AI 비용','매출·비용 입력에서 증빙별 기록'],['예약 게시 실행','Vercel Cron · 5분 주기로 예약 시각 이후 실행'],['연결 만료','OAuth 연결은 토큰 자동 갱신 · 권한 회수 시 재연결'],['실행 실패','콘텐츠 확인 필요 상태와 작업 이력에서 확인']].map(([l,v])=>`<div class="pl-row"><span>${l}</span><span class="caption">${v}</span></div>`).join('')}</section>`;}
function connections(){if(session?.readOnly)return '<section class="panel panel-inner"><h2>보기 전용 계정</h2><p class="panel-desc">운영자가 승인한 현황과 리포트를 확인할 수 있습니다. 계정 승인과 연결 설정은 운영자가 관리합니다.</p></section>';const hub=setupHub();if((state.setupTab||'system')!=='integrations')return hub;return hub+socialSetup()+naverSetup()+disclosure('새 웹사이트 추가',`<form id="service-form" class="form-grid">${formField('서비스 이름','name','','text','required maxlength="60"')}${formField('웹사이트 주소','url','','url','placeholder="https://..."')}<div class="full"><button class="btn primary" type="submit">웹사이트 등록</button><p class="source-note">목록·업무·비용에는 즉시 사용할 수 있습니다. SNS 콘텐츠는 독립 운영합니다. 자동 데이터 수집은 해당 사이트의 DB/API 경로를 확인한 뒤 연결합니다.</p></div></form>`)+`<section class="panel section-gap">${data.services.map(s=>`<div class="connection-item"><div><h2>${esc(s.name)}</h2><p class="overflow-text">${esc(s.root||s.url||s.sitemap||'수집 경로 연결 필요')}</p><p>${esc(s.ref?'Supabase '+s.ref:s.note)}</p></div>${s.url?`<a class="btn" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">사이트 열기 ↗</a>`:(s.sitemap?'<span class="pill gray">'+(s.snapshot?.data?'사이트맵 수집 완료':'사이트맵 조회 필요')+'</span>':'<span class="pill gray">DB/API 연결 필요</span>')}</div>`).join('')}</section>`+disclosure(state.channelEdit?'게시 계정 수정 · 토큰 갱신':'게시 채널 계정 추가',channelForm(),!!state.channelEdit)+`<section class="panel section-gap"><div class="table-head"><h2>게시 계정</h2></div>${data.accounts.filter(a=>!snsRecord(a)||supportedChannel(a.channel)).length?data.accounts.filter(a=>!snsRecord(a)||supportedChannel(a.channel)).map(a=>`<div class="connection-item"><div><h2>${esc(a.label)}</h2><p>${esc(serviceName(a.service))} · ${labels[a.channel]} · ${a.verifiedAt?'계정 확인 '+dt(a.verifiedAt):'저장됨 · 계정 확인 필요'}</p>${a.username?'<p>'+esc(a.username)+'</p>':''}<p class="caption">${a.autoRefresh?'자동 갱신 · 만료 '+dt(a.expiresAt)+' KST':'직접 입력 · 만료 시 재연결 필요'}</p>${a.connectionError?'<p class="warning">'+esc(a.connectionError)+'</p>':''}</div><div class="toolbar">${a.authType==='oauth2'?button('SNS 재연결','social-reconnect',a.id):''}${button('계정 확인','verify',a.id)}${button('수정','channel-edit',a.id)}</div></div>`).join(''):empty('연결된 게시 계정이 없습니다.')}<div class="panel-foot">토큰은 서버에서 암호화해 저장하며, 화면이나 데이터 내보내기에 포함하지 않습니다.</div></section>`+disclosure('AI API 연결',`${data.aiConfig?.configured?`<p class="source-note">\uD0A4 \uC800\uC7A5\uB428 \u00B7 \uC0AC\uC6A9 ${data.aiConfig.enabled?'\uD65C\uC131\uD654':'\uC911\uC9C0'} \u00B7 ${esc(data.aiConfig.provider)} / ${esc(data.aiConfig.model)}</p>`:'<p class="source-note">\uC800\uC7A5\uB41C API \uD0A4 \uC5C6\uC74C</p>'}<form id="ai-form" class="form-grid">${selectField('공급자','provider',[['anthropic','Anthropic'],['openai','OpenAI']],data.aiConfig?.provider||'openai')}${formField('모델 ID','model',data.aiConfig?.model||'','text','required maxlength="120" placeholder="사용할 모델의 정확한 ID"')}${formField('API 키','token','','password',(data.aiConfig?.configured?'':'required ')+(data.aiConfig?.configured?'autocomplete="off" placeholder="\uC800\uC7A5\uB41C \uD0A4 \uC720\uC9C0 \u00B7 \uBCC0\uACBD\uD560 \uB54C\uB9CC \uC785\uB825"':'autocomplete="new-password" placeholder="\uD504\uB85C\uC81D\uD2B8 API \uD0A4 \uC785\uB825"')+' maxlength="5000"')}<label class="check full"><input name="enabled" type="checkbox" ${data.aiConfig?.enabled?'checked':''}>이 키와 모델로 API 사용을 활성화합니다.</label><div class="full"><button class="btn primary" type="submit">AI 연결 저장</button><p class="source-note">모델 공급자의 API 요금과 이용 한도가 적용됩니다. 키는 서버에서 암호화해 저장합니다.</p></div></form>`)+disclosure('내 비밀번호 변경',`<form id="password-form" class="form-grid">${formField('새 비밀번호','password','','password','required minlength="12" maxlength="200" autocomplete="new-password"')}<div class="full"><button class="btn" type="submit">비밀번호 변경</button></div></form>`)+disclosure('최근 관리 이력',table(['시각','계정','작업','대상'],data.audit.slice(0,40).map(a=>row([dt(a.at),esc(a.email),esc(a.action),esc(a.target)]))));}
function naverSetup(){
 const c=data.naver||{},r=c.report,end=new Date(Date.now()+9*36e5-864e5).toISOString().slice(0,10),start=new Date(Date.parse(end+'T00:00:00Z')-29*864e5).toISOString().slice(0,10);
 const link=(url,label)=>webLink(url)?`<a href="${esc(webLink(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);
 const clean=v=>String(v||'').replace(/<\/?b>/gi,'');
 let result='';
 if(r){result=`<div class="full"><h3>마지막 성공 조회 · ${esc({news:'뉴스',webkr:'웹문서',image:'이미지',trend:'검색어트렌드'}[r.mode]||r.mode)}</h3><p class="caption">${dt(r.checkedAt)} KST · ${esc(r.provider)} · ${esc(r.query||r.startDate+' ~ '+r.endDate)}</p>`;
  if(r.mode==='trend')result+='<p class="source-note">0~100 상대 검색 관심도입니다. 월간 검색 횟수·예상 조회수·매출이 아닙니다. 이 조회 구간 안에서만 비교하세요.</p>'+r.results.map(g=>`<h3>${esc(g.title)}</h3>`+table(['날짜','상대 지수'],g.data.map(p=>row([esc(p.period),esc(p.ratio)])))).join('');
  else result+=(r.items||[]).length?table(['제목 / 원문','정보'],r.items.map(i=>row([link(i.originalLink||i.link,clean(i.title)),esc(clean(i.description||i.size||''))+(i.pubDate?'<p class="caption">기사 게시일 '+esc(i.pubDate)+'</p>':'')]))):empty('해당 검색어의 결과가 없습니다.');
  if(r.mode==='trend'&&!r.results.length)result+=empty('해당 기간의 검색어트렌드 결과가 없습니다.');result+='</div>';
 }
 return disclosure('네이버 검색 · 트렌드 조사',`<p class="source-note" style="margin-bottom:20px">${c.configured?'키 저장됨 · 실제 조회 성공 여부는 아래 확인 시각으로 확인하세요.':'NAVER API HUB Application의 인증 정보를 저장하세요.'} 뉴스·웹문서·이미지 검색과 검색어트렌드를 수동 조회합니다. 쇼핑인사이트는 현재 조회하지 않습니다.</p><form id="naver-config-form" class="form-grid"><input type="hidden" name="version" value="${esc(c.version??1)}">${formField('Application 이름','appName',c.appName||'nurione','text','required maxlength="60"')}${formField('Client ID (API Key ID)','apiKeyId','','password',`${c.configured?'':'required '}autocomplete="off" maxlength="500" placeholder="${c.configured?'저장된 값 유지 · 변경할 때만 입력':'X-NCP-APIGW-API-KEY-ID'}"`)}${formField('Client Secret (API Key)','apiKey','','password',`${c.configured?'':'required '}autocomplete="off" maxlength="500" placeholder="${c.configured?'저장된 값 유지 · 변경할 때만 입력':'X-NCP-APIGW-API-KEY'}"`)}<div class="full"><button class="btn" type="submit">네이버 키 암호화 저장</button></div></form>${c.configured?`<form id="naver-research-form" class="form-grid" style="margin-top:28px">${selectField('조회 종류','mode',[['news','뉴스 · 최신순'],['webkr','웹문서'],['image','이미지 · 참고자료'],['trend','검색어트렌드 · 상대 지수']],r?.mode||'news')}${formField('검색어','query',r?.query||r?.results?.[0]?.title||'','text','required maxlength="100" placeholder="예: 포켓몬 행사"')}${formField('트렌드 시작일','startDate',r?.startDate||start,'date','required min="2016-01-01" max="'+end+'"')}${formField('트렌드 종료일','endDate',r?.endDate||end,'date','required min="2016-01-01" max="'+end+'"')}<p class="caption full">날짜는 트렌드 조회에만 적용됩니다(최대366일). 검색은 한 번에 최대10건입니다. 페이지를 열 때 자동 호출하지 않습니다.</p><div class="full"><button class="btn primary" type="submit">자료 조회</button></div>${result}<p class="source-note full">검색 결과는 행사 진행·접수 가능 여부나 이미지 상업사용권을 보증하지 않습니다. 발행 직전 공식 원문에서 날짜·마감·취소·권리를 다시 확인하세요. API HUB 요금·한도 변경은 네이버 콘솔에서 확인하세요.</p></form>`:''}`,true);
}
function channelForm(){const a=data.accounts.find(a=>a.id===state.channelEdit&&snsRecord(a)&&supportedChannel(a.channel));return `<form id="channel-form" class="form-grid"><input type="hidden" name="id" value="${esc(a?.id||'')}">${snsFields}${selectField('채널','channel',Object.entries(labels).filter(([c])=>!manualChannels.has(c)),a?.channel)}${formField('계정 이름','label',a?.label||'','text','required placeholder="예: 누리 공식 Threads"')}${formField('접근 토큰 / WordPress 앱 비밀번호','token','','password',(a?'':'required ')+'autocomplete="off" maxlength="5000"')}${formField('WordPress 주소 · 블로그 선택 시','url',a?.url||'','url','placeholder="https://blog.example.com"')}${formField('WordPress 사용자 이름','username',a?.loginUsername||'','text','autocomplete="off"')}${formField('Instagram API 버전','version',a?.version||'v25.0','text','pattern="v[0-9]+[.]0"')}<div class="full"><button class="btn primary" type="submit">계정 저장</button><p class="source-note">블로그는 WordPress REST API를 연결합니다. Instagram은 프로페셔널 계정과 게시 권한, Threads와 X는 사용자 게시 토큰이 필요합니다. 저장 후 ‘계정 확인’을 실행하세요. API 이용료나 유료 한도는 자동으로 활성화하지 않습니다.</p></div></form>`;}
function reports(){const t=financeTotals();return `<div class="report-summary section-gap"><section class="panel report-box"><span class="pill gray">${state.month} · ${esc(state.scope==='all'?'전체 서비스':serviceName(state.scope))}</span><h3>월간 운영 리포트</h3><p>기록 매출 ${won(t.revenue)}<br>기록 비용 ${won(t.cost)}<br>영업 손익 ${won(t.profit)}<br>${t.complete?'월별 입력 확인 완료':'부분 기록 · 손익 미확인'}</p><div class="toolbar">${button('인쇄 / PDF','print')}${button('거래 CSV','csv')}${button('관리 데이터 JSON','export')}</div></section><section class="panel report-box"><h3>확인할 항목</h3><p>직영 사업장 ${data.businesses.filter(b=>inScope(b.service)&&b.owned&&!b.excluded).length}개<br>미완료 업무 ${data.tasks.filter(t=>inScope(t.service)&&t.status!=='done').length}개<br>콘텐츠 확인 필요 ${data.contents.filter(p=>inScope(p.service)&&(!snsRecord(p)||supportedChannel(p.channel))&&p.status==='review').length}개<br>이전 조회 / 미연결 ${selected().filter(s=>s.stale).length}개 서비스</p><p class="source-note">내보내기는 비밀 키와 게시 토큰을 제외합니다. JSON은 선택 기간의 관리 기록용이며 인증 데이터 백업 파일은 아닙니다.</p></section></div>`+kpis()+sourceTable()+serviceSummary();}
function sync(){const scopes=data.services.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+'</option>').join('');$('scope').innerHTML=automationPage()?'<option value="tistory">SNS 독립 운영</option>':'<option value="all">전체 웹사이트</option>'+scopes;$('scope').disabled=automationPage();$('scope').value=state.scope;renderNavigation();const months=[...new Set([today().slice(0,7),state.month,...data.services.flatMap(s=>(s.snapshot?.data?.monthly||[]).map(r=>r.month)),...data.money.map(r=>r.day.slice(0,7))])].filter(Boolean).sort().reverse();$('period').innerHTML=months.map(m=>'<option value="'+m+'">'+m.slice(0,4)+'년 '+Number(m.slice(5))+'월</option>').join('');$('period').value=state.month;}
function render(){if(!data)return;document.querySelectorAll('.view-switch a').forEach(a=>a.setAttribute('aria-current',a.href.includes('sample=1')===!!data.demo?'page':'false'));const compact=usesCompactDashboard();$('app').classList.toggle('compact-view',compact);if(state.page==='site')state.scope=state.siteId;if(automationPage()){state.scope='tistory';state.business=null;}sync();const p=pages[state.page],title=state.page==='site'?serviceName(state.siteId):state.page==='publish'&&state.channel!=='all'?labels[state.channel]+' · 업로드 현황':p[0];$('page-title').textContent=compact&&state.page==='overview'?'게시 현황':title;$('page-subtitle').textContent=compact?'채널별 게시 여부를 빠르게 확인하세요.':p[1];$('breadcrumb').textContent=compact&&state.page==='overview'?'게시 현황':title;$('period-note').textContent=state.month+(compact?' · ':' · KRW · ')+(state.scope==='all'?'전체 웹사이트':serviceName(state.scope));$('view-time').textContent=dt(data.observedAt)+' KST';const stale=selected().filter(s=>s.stale).length;$('data-status').textContent=data.demo?'샘플 환경 · 실제 게시 없음':stale?'실제 조회 · '+stale+'개 확인 필요':'실제 데이터';$('data-status').className='pill '+(stale?'amber':data.demo?'gray':'');const views={studio:()=>NuriStudio.render('studio'),calendar:()=>NuriStudio.render('calendar'),growth:()=>NuriStudio.render('growth'),overview,businesses:businessPage,finance,partners,content,prompts:promptSettings,history:contentHistory,publish:publishingPage,'publishing-settings':publishingSettingsPage,site:sitePage,traffic,tasks,servers,reports,connections};$('content').innerHTML=compact?mobileDashboard():views[state.page]();applyReadOnly();if(['studio','calendar','growth'].includes(state.page))NuriStudio.mount?.();}
function navigate(page){if(!pages[page])return;if(page!==state.page&&window.NuriStudio?.canLeave&&!NuriStudio.canLeave())return;if(state.page==='site'&&state.siteId==='tistory'&&page==='publish')state.scope='all';state.page=page;if(page==='overview'){state.scope='all';state.channel='all';}if(automationPage()){state.scope='tistory';state.business=null;}if(page==='prompts'){state.channel='all';state.promptService='tistory';}closeSidebar();const update=()=>{render();writeRoute();window.scrollTo(0,0);};if(document.startViewTransition&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){document.startViewTransition(update);}else update();}
async function load(){data=await api('state');readRoute();$('login').classList.add('hidden');$('app').classList.remove('hidden');$('account-name').textContent=session.email;render();}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(){const values=[['거래일','서비스','사업장','유형','분류','거래처','금액','고유번호','근거'],...filteredMoney().map(r=>[r.day,serviceName(r.service),businessName(r.service,r.business),r.kind,r.category,r.partner,r.amount,r.reference,r.note])];const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('NURI-ONE-'+state.month+'.csv','\ufeff'+values.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
async function save(route,body){data=await api(route,body);render();toast('저장했습니다.');}
function openManualUrl(id,route,trigger){const p=data.contents.find(x=>x.id===id);if(session?.readOnly||!p||route==='content/manual'&&!manualBlog(p)||route==='studio/manual'&&(!manualChannels.has(p.channel)&&!manualUrlChannels.has(p.channel)||p.externalId||['published','publishing'].includes(p.status)||manualUrlChannels.has(p.channel)&&p.status==='scheduled'))return toast('직접 게시할 수 있는 초안을 확인하세요.');let dialog=$('manual-url-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='manual-url-dialog';dialog.setAttribute('aria-labelledby','manual-url-title');dialog.className='post-inspector';dialog.style.cssText='width:min(520px,calc(100vw - 32px));padding:22px';const form=document.createElement('form');form.dataset.manualUrlForm='';const heading=document.createElement('h2');heading.id='manual-url-title';heading.textContent='직접 게시한 URL 등록';const label=document.createElement('label');label.className='field';label.htmlFor='manual-url-input';label.textContent='발행 URL';const input=document.createElement('input');input.id='manual-url-input';input.name='url';input.type='url';input.required=true;input.maxLength=2000;input.autocomplete='url';input.placeholder='https://…';input.autofocus=true;label.append(input);const status=document.createElement('p');status.className='action-error';status.setAttribute('role','status');const actions=document.createElement('div');actions.className='toolbar';const cancel=document.createElement('button');cancel.type='button';cancel.className='btn';cancel.textContent='취소';cancel.addEventListener('click',()=>dialog.close());const submit=document.createElement('button');submit.type='submit';submit.className='btn primary';submit.textContent='저장';actions.append(cancel,submit);form.append(heading,label,status,actions);dialog.append(form);document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});dialog.addEventListener('close',()=>{if(dialog.returnFocus?.isConnected)dialog.returnFocus.focus();});form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;submit.disabled=true;status.textContent='';try{data=await api(dialog.route,{id:dialog.contentId,url:input.value,version:dialog.contentVersion});dialog.close();render();toast('직접 게시한 URL을 등록했습니다.');}catch(error){status.textContent=error.message;input.focus();}finally{submit.disabled=false;}});}dialog.route=route;dialog.contentId=id;dialog.contentVersion=p.version;dialog.returnFocus=trigger;dialog.querySelector('[name="url"]').value='';dialog.querySelector('[role="status"]').textContent='';dialog.showModal();dialog.querySelector('[name="url"]').focus();}
