 if(action==='new-content'||action==='generate-content'){state.contentEdit=null;state.draftSeed=null;state.contentStatus='all';navigate('content');const form=$(action==='generate-content'?'generate-form':'content-form');form.closest('details').open=true;form.elements[action==='generate-content'?'topic':'title'].focus();return;}if(action==='inspect-content')return inspectContent(id);if(action==='close-inspector')return $('post-inspector').close();if(action==='inspect-edit'){$('post-inspector').close();state.contentEdit=id;state.channel=data.contents.find(p=>p.id===id)?.channel||'all';state.scope=data.contents.find(p=>p.id===id)?.service||'all';return navigate('content');}if(action==='check-post'){go.disabled=true;data=await api('content/check',{id});render();inspectContent(id);return toast(data.demo?'샘플 상태를 확인했습니다. 실제 채널 조회는 하지 않습니다.':'채널의 게시 확인 결과를 갱신했습니다.');}if(action==='create-channel'){const p=data.contents.find(p=>p.id===id);state.draftSeed={title:p.title,service:p.service,business:p.business,campaignId:campaignKey(p),channel:go.dataset.targetChannel};state.contentEdit=null;state.channel=go.dataset.targetChannel;state.scope=p.service;return navigate('content');}
 if(action==='partner-edit'){state.partnerEdit=id;navigate('partners');return;}if(action==='channel-edit'){state.channelEdit=id;navigate('connections');return;}if(action==='prompt-edit'){const p=data.prompts.find(p=>p.id===id);state.promptService=p.service;state.promptChannel=p.channel;state.scope=p.service;navigate('prompts');$('prompt-form').scrollIntoView({block:'start'});return;}if(action==='plan-edit'){state.planEdit=id;navigate('prompts');return;}if(action==='go')return navigate(id);if(action==='business'){state.business=id;render();return;}if(action==='task-edit'){state.taskEdit=id;navigate('tasks');return;}if(action==='content-edit'){state.contentEdit=id;state.draftSeed=null;state.channel=data.contents.find(p=>p.id===id)?.channel||'all';state.scope=data.contents.find(p=>p.id===id)?.service||'all';navigate('content');return;}
 if(action==='html'){const p=data.contents.find(p=>p.id===id);if(session?.readOnly){download('NURI-content-'+id+'.txt',p.title+'\n\n'+p.body,'text/plain;charset=utf-8');return;}const v=await api('studio/preview',p);download('NURI-content-'+id+'.html',v.document,'text/html;charset=utf-8');return;}if(action==='manual-social-link')return openManualUrl(id,'studio/manual',go);if(action==='studio-open'){NuriStudio.open(id);navigate('studio');return;}if(action==='manual-link')return openManualUrl(id,'content/manual',go);if(action==='copy'){await navigator.clipboard.writeText(data.contents.find(p=>p.id===id).body);return toast('본문을 복사했습니다.');}
