 if(action==='void'){const reason=window.prompt('취소 사유를 입력하세요. 거래는 이력에 남습니다.');if(reason?.trim())await save('money/void',{id,reason});return;}
 if(action==='adsense-connect'){go.disabled=true;const r=await management('adsense',{version:data.adsense.appVersion});location.assign(r.url);return;}if(action==='adsense-report'){go.disabled=true;data=await api('adsense/report',{month:state.month});render();return toast('AdSense 조회 결과를 확인하세요.');}if(action==='google-report'){go.disabled=true;data=await api('google/report',{month:state.month});render();return toast('통계 조회 결과를 확인하세요.');}if(action==='print')return window.print();if(action==='csv')return csv();
